package ama.transcript;
import ama.config.ConfigArchiveSource;import ama.contract.ConfigArchiveContracts.*;import ama.task.*;import java.util.*;import java.util.function.Supplier;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
/** Real service/queue/authority assembly; archive admission and JDBC remain explicit offline substitutes. */
class Task11CombinedInstallationTest {
 static final String PIN="a".repeat(64);static final Ref PROMPT=new Ref(ArtifactType.PROMPT_CONFIG,"v1",PIN),MODEL=new Ref(ArtifactType.MODEL_CONFIG,"v1",PIN);
 static final TranscriptAcquisitionBudget LIMITS=new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,33554432,128,256,256);
 @Test void realSharedAssemblyAcceptsOnlyItsRegisteredQueueSourcesAndServices()throws Exception{
  var f=new Task11PublicationWriteGuardBoundaryTest.Fixture();var c=JdbcTranscriptAuthority.create(f.ds,f.tx,f.access,(a,m,p)->{},mock(ama.storage.FileBackendCatalog.class),Map.of(),f.authority.readBudget(),f.authority.canonicalBudget());var a=c.authority();Supplier<ConfigArchiveSource.Snapshot> archives=()->mock(ConfigArchiveSource.Snapshot.class);var fences=new JdbcSubjectFences(f.ds,Set.of("MEETING"));var outbox=new JdbcOutbox(f.ds,Map.of());var audit=new ama.audit.JdbcAuditAdapter(f.ds);var correction=CorrectionInstallation.compose(new CorrectionInstallation.Declaration("DISABLED_NOT_INSTALLED","1","offline"),List.of());
  try(var admission=mockStatic(SavedTranscriptAdmission.class)){admission.when(()->SavedTranscriptAdmission.capture(any(),any(),any())).thenReturn(new SavedTranscriptAdmission(PIN,a.canonicalBudget(),List.of()));var transcripts=new JdbcSavedTranscripts(a,archives,LIMITS,correction,fences,outbox,audit,new SavedTranscriptTransitions("AUTHORITY_CONTROLLED","AUTHORITY_CONTROLLED","2",List.of(),List.of()));var editor=MinutesEditorRuntime.compose(a,archives,PIN,PROMPT,MODEL,LIMITS,transcripts);var prep=new JdbcMinutesGenerationPreparation(a,archives,PIN,PROMPT,MODEL,LIMITS);var initial=new JdbcMinutesInitialSettings(a,archives,PROMPT,MODEL,LIMITS,fences,outbox,audit);var queue=TranscriptImportRuntime.install(f.ds,fences,outbox,c);var commands=new JdbcMinutesGenerationCommands(a,prep,queue,outbox,audit);var queries=new JdbcMinutesQueries(a,archives,PIN,PROMPT,MODEL,LIMITS);
   assertDoesNotThrow(()->editor.requireCombined(initial,commands,queries));
   var unregistered=new JdbcMinutesGenerationCommands(a,prep,new JdbcTaskQueue(f.ds,fences,outbox,Map.of()),outbox,audit);assertThrows(IllegalArgumentException.class,()->editor.requireCombined(initial,unregistered,queries));
   var arbitrary=new JdbcMinutesGenerationCommands(a,prep,new JdbcTaskQueue(f.ds,fences,outbox,Map.of("MINUTES_GENERATE_V1",a.minutesTaskPolicy(),"KNOWLEDGE_PUBLISH_V1",a.publicationTaskPolicy(),"TRANSCRIPT_IMPORT_V1",a.taskPolicy())),outbox,audit);assertThrows(IllegalArgumentException.class,()->editor.requireCombined(initial,arbitrary,queries));
   var other=JdbcTranscriptAuthority.create(f.ds,f.tx,f.access,(x,m,p)->{},mock(ama.storage.FileBackendCatalog.class),Map.of(),f.authority.readBudget(),f.authority.canonicalBudget());var foreign=new JdbcMinutesGenerationCommands(a,prep,TranscriptImportRuntime.install(f.ds,fences,outbox,other),outbox,audit);assertThrows(IllegalArgumentException.class,()->editor.requireCombined(initial,foreign,queries));
   var changedProfiles=new JdbcMinutesQueries(a,archives,"b".repeat(64),PROMPT,MODEL,LIMITS);assertThrows(IllegalArgumentException.class,()->editor.requireCombined(initial,commands,changedProfiles));assertThrows(IllegalArgumentException.class,()->editor.requireCombined(null,commands,queries));assertTrue(f.sql.isEmpty(),"Assembly verification must not query or write retained resources");
  }
 }
}
